#!/bin/bash
set -e
echo "Updating GTM Intel v2..."
mkdir -p src/lib
echo  | base64 -d > src/lib/research-engine.ts
echo "✓ src/lib/research-engine.ts"
mkdir -p src/app/api/discover
echo  | base64 -d > src/app/api/discover/route.ts
